// HQ Flipboox
float fFrame = (float)Frame;
float fRows  = (float)Rows;
float fCols  = (float)Cols;
float framesPerChannel = Rows * Cols;
float totalFrames = framesPerChannel * 4.0f;

float loopedFrame = fmod(Frame, totalFrames);
loopedFrame = loopedFrame < 0.0f ? loopedFrame + totalFrames : loopedFrame;

int channelIdx = (int)floor(loopedFrame / framesPerChannel);
channelIdx = clamp(channelIdx, 0, 3);

float localFrame = fmod(loopedFrame, framesPerChannel);

float invCols = 1.0f / Cols;
float invRows = 1.0f / Rows;

float colIdx = fmod(floor(localFrame), Cols);
float rowIdx = floor(localFrame / Cols);

float2 clampedUV;
clampedUV.x = clamp(UV.x,0.0f,0.9999f);
clampedUV.y = clamp(UV.y,0.0f,0.9999f);

float2 flipUV;
flipUV.x = (clampedUV.x + colIdx) * invCols;
flipUV.y = (clampedUV.y + rowIdx) * invRows;

flipUV.x = clamp(flipUV.x,colIdx * invCols,(colIdx + 1.0f)*invCols - 0.0001f);
flipUV.y = clamp(flipUV.y,rowIdx * invRows,(rowIdx + 1.0f)*invRows - 0.0001f);

float4 s = Texture2DSample(Tex,TexSampler, flipUV);

float4 channels = float4(s.r, s.g, s.b, s.a);
result = dot(channels, float4(
    (float)(channelIdx == 0),
    (float)(channelIdx == 1),
    (float)(channelIdx == 2),
    (float)(channelIdx == 3)
));

return result;

//-----------Emissive------------------------
float emissiveUV = float2(EmissGrayscale,0.5);
emissiveColor = Texture2DSample(EmissiveRampTex,EmissiveRampTexSampler,emissiveUV);
emissiveColor *= EmissiveIntensity;

return emissiveColor;

